def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    import re

    token_pattern = re.compile(
        r"\s*(<>|<=|>=|[A-Z]+[0-9]*|[0-9]+|[()+*/,:<>=-])"
    )
    precedence = {
        "=": 0, "<>": 0, "<": 0, "<=": 0, ">": 0, ">=": 0,
        "+": 1, "-": 1,
        "*": 2, "/": 2,
        "unary": 3,
    }

    def parse_integer(text):
        negative = text.startswith("-")
        if negative:
            text = text[1:]
        value = 0
        for i in range(0, len(text), 9):
            part = text[i:i + 9]
            value = value * (10 ** len(part)) + int(part)
        return -value if negative else value

    def parse(formula):
        tokens = token_pattern.findall(formula)
        values = []
        operators = []
        expecting_operand = True
        i = 0

        def apply_operator():
            op = operators.pop()
            if op == "unary":
                values.append(("unary", values.pop()))
            else:
                right = values.pop()
                left = values.pop()
                values.append(("binary", op, left, right))

        while i < len(tokens):
            token = tokens[i]

            if token in ("SUM", "MIN", "MAX", "IF"):
                operators.append(("paren", token, len(values)))
                i += 2  # Skip the function name and its opening parenthesis.
                expecting_operand = True
                continue

            if token == "(":
                operators.append(("paren", None, len(values)))
                expecting_operand = True
            elif token == ")":
                while isinstance(operators[-1], str):
                    apply_operator()
                _, function, start = operators.pop()
                if function is not None:
                    args = values[start:]
                    del values[start:]
                    values.append(("function", function, args))
                expecting_operand = False
            elif token == ",":
                while isinstance(operators[-1], str):
                    apply_operator()
                expecting_operand = True
            elif token[0].isdigit():
                values.append(("number", parse_integer(token)))
                expecting_operand = False
            elif token[0].isalpha():
                if i + 1 < len(tokens) and tokens[i + 1] == ":":
                    values.append(("range", token, tokens[i + 2]))
                    i += 2
                else:
                    values.append(("cell", token))
                expecting_operand = False
            else:
                op = "unary" if token == "-" and expecting_operand else token
                while (
                    operators
                    and isinstance(operators[-1], str)
                    and (
                        precedence[operators[-1]] > precedence[op]
                        or (
                            precedence[operators[-1]] == precedence[op]
                            and op != "unary"
                        )
                    )
                ):
                    apply_operator()
                operators.append(op)
                expecting_operand = True
            i += 1

        while operators:
            apply_operator()
        return values[0]

    def range_names(first, last):
        left = min(ord(first[0]), ord(last[0]))
        right = max(ord(first[0]), ord(last[0]))
        top = min(int(first[1:]), int(last[1:]))
        bottom = max(int(first[1:]), int(last[1:]))
        for row in range(top, bottom + 1):
            for column in range(left, right + 1):
                name = chr(column) + str(row)
                if name in cells:
                    yield ("cell", name)

    def argument_nodes(args):
        for arg in args:
            if arg[0] == "range":
                yield from range_names(arg[1], arg[2])
            else:
                yield arg

    def calculate(op, left, right):
        if op == "+":
            return left + right
        if op == "-":
            return left - right
        if op == "*":
            return left * right
        if op == "/":
            if right == 0:
                return "#DIV/0!"
            quotient = abs(left) // abs(right)
            return -quotient if (left < 0) != (right < 0) else quotient
        if op == "=":
            return left == right
        if op == "<>":
            return left != right
        if op == "<":
            return left < right
        if op == "<=":
            return left <= right
        if op == ">":
            return left > right
        return left >= right

    cache = {}
    active = set()

    def evaluate(start):
        tasks = [("cell", start)]
        results = []

        while tasks:
            task = tasks.pop()
            kind = task[0]

            if kind == "cell":
                name = task[1]
                if name not in cells:
                    results.append(0)
                elif name in cache:
                    results.append(cache[name])
                elif name in active:
                    results.append("#CYCLE!")
                else:
                    active.add(name)
                    content = cells[name]
                    tasks.append(("store", name))
                    if content.startswith("="):
                        tasks.append(("eval", parse(content[1:])))
                    else:
                        results.append(parse_integer(content))

            elif kind == "store":
                name = task[1]
                cache[name] = results[-1]
                active.remove(name)

            elif kind == "eval":
                node = task[1]
                node_kind = node[0]

                if node_kind == "number":
                    results.append(node[1])
                elif node_kind == "cell":
                    tasks.append(("cell", node[1]))
                elif node_kind == "unary":
                    tasks.append(("unary",))
                    tasks.append(("eval", node[1]))
                elif node_kind == "binary":
                    tasks.append(("binary_left", node))
                    tasks.append(("eval", node[2]))
                elif node[1] == "IF":
                    tasks.append(("if", node[2]))
                    tasks.append(("eval", node[2][0]))
                else:
                    tasks.append(
                        ("aggregate_next", node[1], iter(argument_nodes(node[2])), None)
                    )

            elif kind == "unary":
                value = results.pop()
                results.append(value if isinstance(value, str) else -value)

            elif kind == "binary_left":
                left = results.pop()
                if isinstance(left, str):
                    results.append(left)
                else:
                    node = task[1]
                    tasks.append(("binary_right", node[1], left))
                    tasks.append(("eval", node[3]))

            elif kind == "binary_right":
                right = results.pop()
                if isinstance(right, str):
                    results.append(right)
                else:
                    results.append(calculate(task[1], task[2], right))

            elif kind == "if":
                condition = results.pop()
                if isinstance(condition, str):
                    results.append(condition)
                else:
                    args = task[1]
                    tasks.append(("eval", args[1] if condition else args[2]))

            elif kind == "aggregate_next":
                function, iterator, accumulated = task[1:]
                node = next(iterator, None)
                if node is None:
                    results.append(0 if accumulated is None else accumulated)
                else:
                    tasks.append(("aggregate_value", function, iterator, accumulated))
                    tasks.append(("eval", node))

            else:  # aggregate_value
                function, iterator, accumulated = task[1:]
                value = results.pop()
                if isinstance(value, str):
                    results.append(value)
                else:
                    if accumulated is None:
                        accumulated = value
                    elif function == "SUM":
                        accumulated += value
                    elif function == "MIN":
                        accumulated = min(accumulated, value)
                    else:
                        accumulated = max(accumulated, value)
                    tasks.append(("aggregate_next", function, iterator, accumulated))

        return results.pop()

    return {name: evaluate(name) for name in cells}
